INSERT INTO public.auth_reauth_ticket (
    subject_type, subject_id, ticket_hash, allowed_action, verify_method,
    status, expires_at, created_by, updated_by
) VALUES (
    #{subjectType}, #{subjectId}, #{ticketHash}, #{allowedAction}, #{verifyMethod},
    'ACTIVE', #{expiresAt}, #{subjectId}, #{subjectId}
)

mapper.update:
UPDATE public.auth_reauth_ticket
SET status = 'CONSUMED',
    consumed_time = CURRENT_TIMESTAMP,
    updated_by = #{subjectId},
    updated_time = CURRENT_TIMESTAMP,
    version = version + 1
WHERE id = #{ticketId}
  AND subject_type = #{subjectType}
  AND subject_id = #{subjectId}
  AND allowed_action = #{allowedAction}
  AND status = 'ACTIVE'
  AND expires_at > CURRENT_TIMESTAMP
  AND version = #{version}
  AND is_deleted = false
